/// First slot of rest role `role` in nodes of `kind`.
fn restSlotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"routine" => if (role == .@"lines") 1 else null,
        .@"label" => if (role == .@"cmds") 4 else null,
        .@"line" => if (role == .@"cmds") 2 else null,
        .@"commands" => if (role == .@"cmds") 1 else null,
        .@"set" => if (role == .@"args") 2 else null,
        .@"new" => if (role == .@"args") 2 else null,
        .@"kill" => if (role == .@"args") 2 else null,
        .@"merge" => if (role == .@"args") 2 else null,
        .@"do" => if (role == .@"args") 2 else null,
        .@"goto" => if (role == .@"args") 2 else null,
        .@"break" => if (role == .@"args") 2 else null,
