        .@"zsystem" => if (role == .@"args") 2 else null,
        .@"if" => if (role == .@"conds") 1 else null,
        .@"for" => if (role == .@"params") 2 else null,
        .@"setmulti" => if (role == .@"targets") 2 else null,
        .@"setfn" => if (role == .@"args") 3 else null,
        .@"exclusive" => if (role == .@"names") 1 else null,
        .@"control" => if (role == .@"args") 2 else null,
        .@"posformat" => if (role == .@"marks") 2 else null,
        .@"lock=" => if (role == .@"refs") 2 else null,
        .@"lock+" => if (role == .@"refs") 2 else null,
