/// Parse a whole gotoarg with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseGotoarg(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
